solution:
import kotlinx.coroutines.*

suspend fun loadPrice(name: String): Int {
    delay(10)
    return name.length * 10
}

suspend fun totalParallel(): Int = coroutineScope {
    val bread = async { loadPrice("хлеб") }
    val cheese = async { loadPrice("сыр") }
    bread.await() + cheese.await()
}

